package ychatapp.model.dao;
import java.sql.*; import java.util.*; import ychatapp.model.beans.PollOption;
public class PollDAO {
 private static volatile boolean tablesChecked = false; public PollDAO(){ if(!tablesChecked){ synchronized(PollDAO.class){ if(!tablesChecked){ createTablesIfNotExists(); tablesChecked = true; } } } } private Connection getConnection() throws Exception{return DBConnection.getConnection();}
 private void createTablesIfNotExists(){String[] ddl={"CREATE TABLE IF NOT EXISTS post_polls (id INT AUTO_INCREMENT PRIMARY KEY, post_id INT NOT NULL UNIQUE, question VARCHAR(500) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4","CREATE TABLE IF NOT EXISTS post_poll_options (id INT AUTO_INCREMENT PRIMARY KEY, poll_id INT NOT NULL, option_text VARCHAR(255) NOT NULL, FOREIGN KEY(poll_id) REFERENCES post_polls(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4","CREATE TABLE IF NOT EXISTS post_poll_votes (id INT AUTO_INCREMENT PRIMARY KEY, poll_id INT NOT NULL, option_id INT NOT NULL, user_id INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_post_poll_user(poll_id,user_id), FOREIGN KEY(poll_id) REFERENCES post_polls(id) ON DELETE CASCADE, FOREIGN KEY(option_id) REFERENCES post_poll_options(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"};try(Connection c=getConnection();Statement s=c.createStatement()){for(String q:ddl)s.executeUpdate(q);}catch(Exception e){e.printStackTrace();}}
 public boolean savePoll(int postId,String question,List<String> options){if(postId<1||question==null||question.trim().isEmpty()||options==null)return false;List<String> clean=new ArrayList<>();for(String x:options)if(x!=null&&!x.trim().isEmpty())clean.add(x.trim());if(clean.size()<2||clean.size()>6)return false;try(Connection c=getConnection()){c.setAutoCommit(false);try{int id;try(PreparedStatement p=c.prepareStatement("INSERT INTO post_polls(post_id,question) VALUES(?,?)",Statement.RETURN_GENERATED_KEYS)){p.setInt(1,postId);p.setString(2,question.trim());p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){if(!r.next())throw new SQLException("Poll ID not generated");id=r.getInt(1);}}try(PreparedStatement p=c.prepareStatement("INSERT INTO post_poll_options(poll_id,option_text) VALUES(?,?)")){for(String x:clean){p.setInt(1,id);p.setString(2,x);p.addBatch();}p.executeBatch();}c.commit();return true;}catch(Exception e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}catch(Exception e){e.printStackTrace();return false;}}
 public String getPollQuestion(int postId){try(Connection c=getConnection();PreparedStatement p=c.prepareStatement("SELECT question FROM post_polls WHERE post_id=?")){p.setInt(1,postId);try(ResultSet r=p.executeQuery()){if(r.next())return r.getString(1);}}catch(Exception e){e.printStackTrace();}return null;}
 public List<PollOption> getPollOptions(int postId,int userId){List<PollOption> out=new ArrayList<>();String q="SELECT o.id,o.option_text,COUNT(v.id) votes,(SELECT COUNT(*) FROM post_poll_votes uv WHERE uv.poll_id=p.id AND uv.user_id=?) voted,(SELECT COUNT(*) FROM post_poll_votes av WHERE av.poll_id=p.id) total FROM post_polls p JOIN post_poll_options o ON o.poll_id=p.id LEFT JOIN post_poll_votes v ON v.option_id=o.id WHERE p.post_id=? GROUP BY p.id,o.id,o.option_text ORDER BY o.id";try(Connection c=getConnection();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,userId);p.setInt(2,postId);try(ResultSet r=p.executeQuery()){while(r.next()){PollOption o=new PollOption();o.setId(r.getInt("id"));o.setPostId(postId);o.setOptionText(r.getString("option_text"));o.setVoteCount(r.getInt("votes"));int total=r.getInt("total");o.setPercentage(total==0?0:Math.round(o.getVoteCount()*100f/total));o.setVotedByCurrentUser(r.getInt("voted")>0);out.add(o);}}}catch(Exception e){e.printStackTrace();}return out;}
 public boolean castVote(int postId,int optionId,int userId){String q="INSERT INTO post_poll_votes(poll_id,option_id,user_id) SELECT p.id,o.id,? FROM post_polls p JOIN post_poll_options o ON o.poll_id=p.id WHERE p.post_id=? AND o.id=? ON DUPLICATE KEY UPDATE option_id=VALUES(option_id),created_at=CURRENT_TIMESTAMP";try(Connection c=getConnection();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,userId);p.setInt(2,postId);p.setInt(3,optionId);return p.executeUpdate()>0;}catch(Exception e){e.printStackTrace();return false;}}
}
